      subtitle: "Common questions from international buyers and investors",
      questions: [
        { q: "Can foreigners buy property in USA?", a: "Yes — there are NO federal restrictions on foreign nationals buying US property. However, some states restrict certain nationalities buying near military bases, and Canada currently has a residential foreign buyer ban (this is Canada, not USA). In the USA, any nationality can buy residential or commercial property freely." },
        { q: "Do I need a US visa to buy property in the USA?", a: "No. Property purchase does NOT require a US visa. However, you'll need an ITIN (Individual Tax Identification Number) to file US tax returns on rental income. Visiting the USA for property purchase is allowed on a tourist/business visa." },
        { q: "What is FIRPTA and how does it affect me as a foreign seller?", a: "FIRPTA (Foreign Investment in Real Property Tax Act) requires 15% of the gross sale price to be withheld when a foreign national sells US property. This is not a final tax — it's a withholding deposited with the IRS. You file a US tax return and get back any excess. Net gain after deductions is what's actually taxed." },
        { q: "Which US states have no income tax for rental income?", a: "Florida, Texas, Nevada, Washington, and Wyoming have no state income tax — making them popular for foreign investors. Note that federal income tax still applies regardless of state. California has the highest state tax at up to 13.3%." },
        { q: "Can I get a US mortgage as a foreign national?", a: "Yes, but expect 30–40% down payment requirements and higher interest rates vs US citizens. You'll need 12 months of foreign bank statements, proof of income, and sometimes a letter from your home country bank. DSCR loans (based on rental income, not personal income) are increasingly popular for foreign investors." },
        { q: "What is EB-5 visa and can I get a Green Card through US property?", a: "The EB-5 visa requires $800,000 (rural/TEA) or $1.05M (urban) invested in a US business that creates 10 full-time jobs. You cannot get a Green Card simply by buying a house — the EB-5 requires an active business investment, typically through an approved Regional Center. Processing takes 24–36 months." },
      ],
